const foods=[
['Bara','बरा','Meals','Lentil dumplings in buttermilk, with a mustard-seed tempering.',140,'1 bowl'],
['Meeda','मीड़ा','Meals','Tender gram-flour pieces in a light tomato and onion gravy.',160,'1 bowl'],
['Maheri','महेरी','Meals','Broken wheat slow-cooked with buttermilk. Simple, comforting food.',120,'1 bowl'],
['Besan ke Aaloo','बेसन के आलू','Savouries','Chickpea-flour and dried-amla dumplings, sliced and roasted in ghee.',150,'1 plate'],
['Thopa','थोपा','Savouries','Seasoned chickpea-flour squares, a regional savoury favourite.',120,'1 plate'],
['Baffori','बफौरी','Savouries','Steamed chickpea-flour dumplings tossed with warming spices.',140,'1 plate'],
['Karar','करार','Meals','A spiced split-green-gram preparation, cooked in the style of kadhi.',150,'1 bowl'],
['Fara','फरा','Savouries','Boiled wheat-flour dumplings seasoned with cumin and chilli.',130,'1 plate'],
['Ras Kheer','रस खीर','Sweets','A regional milk dessert with sugarcane juice and mahua flowers.',110,'1 bowl'],
['Lapsi','लपसी','Sweets','Sweet broken wheat cooked with ghee and dried fruits.',100,'1 bowl'],
['Anarsa','अनरसा','Sweets','Crisp rice-flour sweets made with jaggery or sugar.',180,'250 g'],
['Puri ke Laddoo','पूरी के लड्डू','Sweets','Crumbled fried gram-flour bread brought together with ghee and sweetness.',220,'250 g']
];
const cart=new Map();let category='All food';const money=n=>'₹'+n;const el=id=>document.getElementById(id);el('year').textContent=new Date().getFullYear();el('hero-photo').src='thali.jpg';
function render(){el('filters').innerHTML=['All food','Meals','Savouries','Sweets'].map(c=>`<button class="${category===c?'active':''}" aria-pressed="${category===c}" data-category="${c}">${c}</button>`).join('');el('products').innerHTML=foods.map((f,i)=>({f,i})).filter(({f})=>category==='All food'||f[2]===category).map(({f,i})=>`<article class="product"><span class="category">${f[2]} · Bundelkhand</span><h3>${f[0]}</h3><span class="hindi" lang="hi">${f[1]}</span><p>${f[3]}</p><div class="product-bottom"><strong>${money(f[4])}<small>/ ${f[5]}</small></strong><button class="add" data-add="${i}" aria-label="Add ${f[0]} to basket">Add +</button></div></article>`).join('')}
function renderCart(){let n=0,total=0;el('cart-items').innerHTML=[...cart].map(([i,q])=>{n+=q;total+=foods[i][4]*q;return `<div class="cart-row"><div>${foods[i][0]}<small>${money(foods[i][4])} / ${foods[i][5]}</small></div><div class="qty"><button data-change="${i}" data-delta="-1" aria-label="Remove one ${foods[i][0]}">−</button><span>${q}</span><button data-change="${i}" data-delta="1" aria-label="Add one ${foods[i][0]}">+</button></div></div>`}).join('')||'<p>Your basket is waiting for a little Bundeli flavour. Explore the collection to add your favourites.</p>';el('count').textContent=n;el('total').textContent=money(total)}
let timer;function add(i){cart.set(i,(cart.get(i)||0)+1);renderCart();el('notice').textContent=foods[i][0]+' added to your basket';el('notice').classList.add('show');clearTimeout(timer);timer=setTimeout(()=>el('notice').classList.remove('show'),2200)}
if(document.modelContext?.registerTool){const lifecycle=new AbortController();try{Promise.resolve(document.modelContext.registerTool({name:'stage_bundeli_basket',description:'Add dishes to the preview basket. This does not place an order or take payment.',inputSchema:{type:'object',properties:{dishNames:{type:'array',items:{type:'string'},minItems:1,maxItems:20}},required:['dishNames'],additionalProperties:false},annotations:{readOnlyHint:false,untrustedContentHint:false},execute(input){if(!input||!Array.isArray(input.dishNames)||input.dishNames.length<1||input.dishNames.length>20)throw new Error('Provide between 1 and 20 dish names.');const ids=input.dishNames.map(n=>foods.findIndex(f=>f[0]===n));if(ids.some(i=>i<0))throw new Error('Unknown dish name. Use names shown in the collection.');ids.forEach(add);return {status:'preview_only',items:[...cart].map(([i,quantity])=>({dish:foods[i][0],quantity})),subtotal:[...cart].reduce((s,[i,q])=>s+foods[i][4]*q,0),currency:'INR'}}},{signal:lifecycle.signal})).catch(()=>{});window.addEventListener('pagehide',()=>lifecycle.abort(),{once:true})}catch{}}
el('filters').addEventListener('click',e=>{const b=e.target.closest('[data-category]');if(b){category=b.dataset.category;render()}});el('products').addEventListener('click',e=>{const b=e.target.closest('[data-add]');if(b)add(Number(b.dataset.add))});el('cart-items').addEventListener('click',e=>{const b=e.target.closest('[data-change]');if(!b)return;const i=Number(b.dataset.change),q=(cart.get(i)||0)+Number(b.dataset.delta);if(q<=0)cart.delete(i);else cart.set(i,q);renderCart()});el('bag').onclick=()=>el('cart').showModal();el('close').onclick=el('continue').onclick=()=>el('cart').close();el('cart').addEventListener('click',e=>{if(e.target===el('cart')){const r=el('cart').getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)el('cart').close()}});render();renderCart();
